# Страницы современных моделей: поколения и моторы с цифрами, история изменений, свежие новости, частые проблемы.
# Цифры — из data.json (выгрузка приложения: export4.js), тексты — с источниками. Непроверенное — «уточняется».
# Выполняется через exec() в конце articles.py: A, add, D, table, ul, tip, warn, E доступны.
import datetime as _dt6

_M = {m["id"]: m for m in D["models"]}


def _src(url, name):
    return f'<a class="inlink" href="{url}" target="_blank" rel="noopener">{E(name)}</a>'


def _eng(fam, eid):
    return next(e for e in D["fams"][fam]["engines"] if e["id"] == eid)


def _v(g, e, field):
    return g["v"].get(field) or e["v"].get(field) or ""


def _numcell(x):
    return f'<span class="un">{E(x)}</span>' if str(x).startswith("уточняется") else f'<span class="num">{E(x)}</span>'


def _gens(mid):
    out = ""
    for g in reversed(_M[mid]["gens"]):   # сначала самое новое поколение
        out += f'<h3>{E(g["name"])} <small>— {E(g["years"])}</small></h3>'
        if g.get("note"): out += tip(E(g["note"]))
        cards = ""
        for eid in g["engs"]:
            e = _eng(g["fam"], eid)
            pk = _v(g, e, "plugKey")
            plug = pk if str(pk).startswith("уточняется") else f'ключ {pk} · {_v(g, e, "plugTorque")}'
            rows = [("Масло на замену", _numcell(_v(g, e, "oil"))), ("Свечи: ключ и момент", _numcell(plug)), ("Привод ГРМ", E(_v(g, e, "grm")))]
            cards += f'<div class="ecard"><b>{E(e["name"])}</b><small>{E(e["sub"])}</small><dl>' + "".join(f"<dt>{a}</dt><dd>{b}</dd>" for a, b in rows) + "</dl></div>"
        out += f'<div class="ecards">{cards}</div>'
        out += f'<p><a class="inlink" href="../?gen={g["id"]}#numbers">Все цифры для «{E(g["name"])}» в Гаражнике →</a></p>'
    return out


def _timeline(items):
    return '<ul class="tline">' + "".join(f'<li><b>{E(d)}</b> {t}</li>' for d, t in items) + "</ul>"


def _jobs(gid, fam):
    J = [("oil", "Замена масла и фильтра"), ("plugs", "Замена свечей"), ("air", "Воздушный фильтр"), ("cabin", "Салонный фильтр"),
         ("coolant", "Замена антифриза"), ("padsreplace", "Замена передних колодок"), ("bleed", "Тормозная жидкость"),
         ("timing", "ГРМ"), ("altbelt", "Ремень генератора"), ("battery", "Аккумулятор"), ("bulbs", "Лампы")]
    if fam in ("kpg", "vesta"): J += [("stablink", "Стойки стабилизатора"), ("hub", "Ступичный подшипник")]
    return ul([f'<a class="inlink" href="../?gen={gid}#{j}">{E(t)}</a>' for j, t in J]) + \
        f'<p>Что-то сломалось — <a class="inlink" href="../?gen={gid}#symptoms">поломки по симптомам</a>, <a class="inlink" href="../?gen={gid}#lamps">лампы на панели</a>, <a class="inlink" href="../?gen={gid}#codes">коды ошибок</a>.</p>'


def _sched(fam):
    rows = []
    for s in D["sched"][fam]:
        when = []
        if s["km"]: when.append(f'каждые {s["km"]:,} км'.replace(",", " "))
        if s["years"]: when.append("раз в год" if s["years"] == 1 else f'раз в {s["years"]} {"года" if s["years"] < 5 else "лет"}')
        rows.append([E(s["name"]), f'<span class="num">{" или ".join(when)}</span>'])
    return table(["Что", "Когда"], rows) + tip("Ориентир по типовому регламенту. Для новых моторов интервалы сверяй с сервисной книжкой своей машины.")


